import{_ as t,o,c as r,a3 as a}from"./chunks/framework.cNy3aYYk.js";const m=JSON.parse('{"title":"Owner credentials + stale workspace header — Production Readiness","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Owner credentials + stale workspace header — Production Readiness | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/deployment/owner-access-stale-tenant-header-production-readiness"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Owner credentials + stale workspace header — Production Readiness | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/deployment/owner-access-stale-tenant-header-production-readiness"}]]},"headers":[],"relativePath":"deployment/owner-access-stale-tenant-header-production-readiness.md","filePath":"deployment/owner-access-stale-tenant-header-production-readiness.md","lastUpdated":1794259478000}'),n={name:"deployment/owner-access-stale-tenant-header-production-readiness.md"};function s(d,e,i,l,c,h){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="owner-credentials-stale-workspace-header-—-production-readiness" tabindex="-1">Owner credentials + stale workspace header — Production Readiness <a class="header-anchor" href="#owner-credentials-stale-workspace-header-—-production-readiness" aria-label="Permalink to &quot;Owner credentials + stale workspace header — Production Readiness&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td><strong>Date</strong></td><td>2026-10-21</td></tr><tr><td><strong>Status</strong></td><td><strong>Go for production</strong> — headed Playwright <strong>2/2</strong> (setup + one serial session)</td></tr><tr><td><strong>Scope</strong></td><td>Shared-host <code>X-Tenant-Domain</code> / Bearer conflict; Central update of workspace owner login email/password</td></tr><tr><td><strong>Catalog</strong></td><td>No bump</td></tr><tr><td><strong>Companion</strong></td><td><a href="/developer-guide/authentication">Authentication</a> · <a href="/user-guide/admin-ui">Admin UI</a> · <a href="/api/central-v1">Central API</a> · <a href="/changelog/">CHANGELOG</a></td></tr></tbody></table><hr><h2 id="executive-summary" tabindex="-1">Executive summary <a class="header-anchor" href="#executive-summary" aria-label="Permalink to &quot;Executive summary&quot;">​</a></h2><p>On the shared SPA host, a leftover <code>dc_saas_tenant_domain</code> (sent as <code>X-Tenant-Domain</code>) could bind the wrong workspace for forgot/reset or 401 Central impersonation when the Bearer belonged to another tenant. Central also lacked a way to set the workspace <strong>owner login</strong> email/password after create (the Tenants list <strong>Email</strong> column is contact-only).</p><p>This ship: token/email win over stale headers; SPA omits the header when a Bearer is present and resets the hint on impersonation start; Central <strong>Owner login</strong> updates owner credentials with audit.</p><p><strong>Go / No-Go:</strong> <strong>Go.</strong> Deploy Backend + Frontend + Docs together. No migrate.</p><table tabindex="0"><thead><tr><th>Gate</th><th>Result</th></tr></thead><tbody><tr><td>Platform freeze</td><td><strong>Pass</strong> — existing Central tenant details + axios interceptors</td></tr><tr><td>Forgot/reset prefer email over stale <code>X-Tenant-Domain</code></td><td><strong>Pass</strong> (Pest <code>StaleWorkspaceHeaderAuthTest</code>)</td></tr><tr><td>Bearer token wins over conflicting header</td><td><strong>Pass</strong> (Pest)</td></tr><tr><td>Central owner email/password update + token revoke</td><td><strong>Pass</strong> (Pest <code>TenantUpdateOwnerCredentialsTest</code>)</td></tr><tr><td>Impersonation start returns <code>workspace</code> slug/domain</td><td><strong>Pass</strong> (Pest <code>ImpersonationTest</code>)</td></tr><tr><td>Axios omits <code>X-Tenant-Domain</code> with Bearer</td><td><strong>Pass</strong> (Vitest <code>axios.test.ts</code>)</td></tr><tr><td>Headed one-session: validate owner login, save, impersonate with stale hint, audit</td><td><strong>Pass</strong> (<code>npm run test:e2e:owner-credentials:headed</code>, 2026-10-21)</td></tr></tbody></table><hr><h2 id="security-summary" tabindex="-1">Security summary <a class="header-anchor" href="#security-summary" aria-label="Permalink to &quot;Security summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Control</th><th>Status</th></tr></thead><tbody><tr><td>Owner credentials require <code>tenants.update</code></td><td>Pass</td></tr><tr><td>Password never written to audit properties (flags only)</td><td>Pass</td></tr><tr><td>Password change revokes owner Sanctum tokens</td><td>Pass</td></tr><tr><td>Owner email uniqueness still global on <code>users.email</code></td><td>Pass</td></tr><tr><td>Stale client header cannot override Bearer or auth email resolution</td><td>Pass</td></tr></tbody></table><hr><h2 id="findings-disposition" tabindex="-1">Findings disposition <a class="header-anchor" href="#findings-disposition" aria-label="Permalink to &quot;Findings disposition&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>Severity</th><th>Item</th><th>Disposition</th></tr></thead><tbody><tr><td><strong>A1</strong></td><td><strong>High</strong></td><td>Stale <code>X-Tenant-Domain</code> caused impersonation 401 / reset “user not found” on shared host</td><td><strong>Fixed</strong> — token/email win in <code>InitializeTenancy</code>; SPA skips header with Bearer; impersonation replaces storage hint</td></tr><tr><td><strong>A2</strong></td><td><strong>High</strong></td><td>Operators could not set owner login email/password from Central after create</td><td><strong>Fixed</strong> — <code>POST /tenants/{id}/owner-credentials</code> + <strong>Owner login</strong> dialog</td></tr><tr><td><strong>A3</strong></td><td>Med</td><td>Tenants list <strong>Email</strong> confused with owner login email</td><td><strong>Documented</strong> — Admin UI + Owner login copy; Overview already shows Owner email</td></tr><tr><td><strong>A4</strong></td><td>Low</td><td>Audit list omitted new owner-credential property keys</td><td><strong>Fixed</strong> — allowlist includes <code>owner_id</code>, <code>owner_email</code>, <code>email_changed</code>, <code>password_changed</code></td></tr><tr><td><strong>I1</strong></td><td>Info</td><td>Clearing localStorage was a workable ops workaround</td><td><strong>Superseded</strong> by product fix</td></tr></tbody></table><hr><h2 id="headed-browser-coverage" tabindex="-1">Headed browser coverage <a class="header-anchor" href="#headed-browser-coverage" aria-label="Permalink to &quot;Headed browser coverage&quot;">​</a></h2><p><code>E2E_BROWSER_CHANNEL=chrome npm run test:e2e:owner-credentials:headed</code> on 2026-10-21. Result: <strong>2 passed</strong> (central login setup + one serial session).</p><p>One Central admin session (<code>e2e/.auth/admin.json</code>):</p><ol><li>Create tenant with distinct contact email vs owner email</li><li><strong>Owner login</strong> — empty submit → validation; password mismatch → validation</li><li>Save new owner email + password → toast + Overview shows new owner email</li><li>Inject stale <code>dc_saas_tenant_domain</code> → <strong>Impersonate</strong> (reason validation then success)</li><li>After verify + reload, impersonation banner visible; storage hint is <strong>not</strong> the stale domain</li><li>End impersonation → Central Dashboard → tenant Audit Logs show <code>workspace_owner_credentials_updated</code> and <code>impersonation_started</code></li><li>Delete tenant</li></ol><p><strong>Finding during e2e:</strong> success toast overlay blocked the Impersonate submit click — test waits for toast dismiss (product toast timing unchanged).</p><hr><h2 id="upgrade" tabindex="-1">Upgrade <a class="header-anchor" href="#upgrade" aria-label="Permalink to &quot;Upgrade&quot;">​</a></h2><ol><li>Deploy Backend (no migrate).</li><li>Deploy Frontend SPA and hard-refresh.</li><li>Deploy Docs.</li><li>Smoke: open a workspace → <strong>Owner login</strong> set a temp password → Impersonate with another workspace previously visited on the same browser (stale hint) → confirm no “Unauthenticated” / session-expired loop.</li><li>Smoke: shared-host forgot-password with the owner email after visiting a different workspace subdomain in the same browser.</li></ol>',23)])])}const p=t(n,[["render",s]]);export{m as __pageData,p as default};
